SELECT 
    d.name as deviceName,
    d.id as deviceId,
    COALESCE(SUM(di.value), 0) as sumValue
FROM device d
LEFT JOIN data_item di ON d.id = di.device_id 
    AND di.time_type = #{timeType}

        AND YEAR(di.data_time) = #{year}


        AND MONTH(di.data_time) = #{month}



        AND d.id = #{deviceId}


GROUP BY d.id, d.name
ORDER BY sumValue DESC

SELECT
    ps.id as powerStationId,
    ps.name as powerStationName,

        DATE_FORMAT(di.data_time, '%Y-%m-%d %H') as timeBucket,
        DATE_FORMAT(di.data_time, '%Y-%m-%d') as timeBucket,
        DATE_FORMAT(di.data_time, '%Y-%m') as timeBucket,

    COALESCE(SUM(di.value), 0) as sumValue
FROM power_station ps
LEFT JOIN device d ON d.power_station_id = ps.id AND d.ammeter = 0
LEFT JOIN data_item di ON di.device_id = d.id AND di.time_type = #{dbTimeType}
    AND YEAR(di.data_time) = #{year}
    AND MONTH(di.data_time) = #{month}
    AND DAY(di.data_time) = #{day}

    AND ps.id = #{powerStationId}

GROUP BY ps.id, ps.name, timeBucket
ORDER BY ps.name ASC, timeBucket ASC

SELECT ps.id as powerStationId, ps.name as powerStationName,
DATE_FORMAT(di.data_time, '%Y-%m-%d') as timeBucket, DATE_FORMAT(di.data_time, '%Y-%m') as timeBucket, YEAR(di.data_time) as timeBucket,
COALESCE(SUM(di.value), 0) as sumValue FROM power_station ps LEFT JOIN device d ON d.power_station_id = ps.id AND d.ammeter = 0 LEFT JOIN data_item di ON di.device_id = d.id AND di.time_type = #{timeType} AND di.data_time >= #{startDate} AND di.data_time <= #{endDate}
AND ps.id = #{powerStationId}
GROUP BY ps.id, ps.name, timeBucket ORDER BY ps.name ASC, timeBucket ASC
